function showEpipolarLines(mocapJoints, vue2, vue4, frameNumber)
% this func displays corresponding epipolar lines in the vue2 & vue4 imgs.
%
% the epipolar line in 1 cam is generated by back-projecting
% a point from the other cam into a 3D ray, selecting 2 points
% on that ray, & projecting those points into the 1st cam.

    % ensure all 12 joints are valid in the selected frame
    confidence = mocapJoints(frameNumber, :, 4);

    if ~all(confidence == 1)
        error('The selected frame does not have all 12 valid joints.');
    end

    % extract & project the OG 3D joints
    joints3D = squeeze(mocapJoints(frameNumber, :, 1:3));

    pointsVue2 = myProjectPoints(joints3D, vue2);
    pointsVue4 = myProjectPoints(joints3D, vue4);

    % back-project the pixels into world-coordinate viewing rays
    [centerVue2, raysVue2] = myPixelToRay(pointsVue2, vue2);
    [centerVue4, raysVue4] = myPixelToRay(pointsVue4, vue4);

    % read the corresponding video frames
    vue2video = VideoReader( ...
        'Subject4-Session3-24form-Full-Take4-Vue2.mp4');

    vue4video = VideoReader( ...
        'Subject4-Session3-24form-Full-Take4-Vue4.mp4');

    videoTime = (frameNumber - 1) / 100;

    vue2video.CurrentTime = videoTime;
    vid2Frame = readFrame(vue2video);

    vue4video.CurrentTime = videoTime;
    vid4Frame = readFrame(vue4video);

    imageHeight = size(vid2Frame, 1);
    imageWidth = size(vid2Frame, 2);

    % 1 matching color for each joint in both views
    jointColors = lines(12);

    figure('Position', [100, 100, 1500, 600]);
    tiledlayout(1, 2, ...
        'TileSpacing', 'compact', ...
        'Padding', 'compact');

    %% epipolar lines in vue2

    nexttile;
    image(vid2Frame);
    axis image;
    hold on;

    for joint = 1:12
        % choose 2 points on the vue4 viewing ray
        rayPoint1 = centerVue4 + 1000 * raysVue4(joint, :);
        rayPoint2 = centerVue4 + 10000 * raysVue4(joint, :);

        % project the vue4 ray into vue2
        projectedRay = myProjectPoints( ...
            [rayPoint1; rayPoint2], vue2);

        drawImageLine( ...
            projectedRay(1, :), ...
            projectedRay(2, :), ...
            imageWidth, imageHeight, ...
            jointColors(joint, :));

        plot(pointsVue2(joint, 1), pointsVue2(joint, 2), ...
            'o', ...
            'Color', jointColors(joint, :), ...
            'MarkerFaceColor', jointColors(joint, :), ...
            'MarkerSize', 7);
    end

    title(['Vue2 Epipolar Lines — Frame ', num2str(frameNumber)]);
    xlabel('Pixel x');
    ylabel('Pixel y');

    %% epipolar lines in vue4

    nexttile;
    image(vid4Frame);
    axis image;
    hold on;

    for joint = 1:12
        % choose 2 points on the vue2 viewing ray
        rayPoint1 = centerVue2 + 1000 * raysVue2(joint, :);
        rayPoint2 = centerVue2 + 10000 * raysVue2(joint, :);

        % project the vue2 ray into vue4
        projectedRay = myProjectPoints( ...
            [rayPoint1; rayPoint2], vue4);

        drawImageLine( ...
            projectedRay(1, :), ...
            projectedRay(2, :), ...
            imageWidth, imageHeight, ...
            jointColors(joint, :));

        plot(pointsVue4(joint, 1), pointsVue4(joint, 2), ...
            'o', ...
            'Color', jointColors(joint, :), ...
            'MarkerFaceColor', jointColors(joint, :), ...
            'MarkerSize', 7);
    end

    title(['Vue4 Epipolar Lines — Frame ', num2str(frameNumber)]);
    xlabel('Pixel x');
    ylabel('Pixel y');

    sgtitle('Two-View Epipolar Geometry');

end


function drawImageLine(point1, point2, imageWidth, imageHeight, lineColor)
% this func draws the infinite line thru 2 points,
% clipped to the image borders.

    homogeneousPoint1 = [point1, 1];
    homogeneousPoint2 = [point2, 1];

    lineEquation = cross(homogeneousPoint1, homogeneousPoint2);

    a = lineEquation(1);
    b = lineEquation(2);
    c = lineEquation(3);

    intersections = [];

    % intersections w left & right image borders
    if abs(b) > eps
        yLeft = -(a + c) / b;
        yRight = -(a * imageWidth + c) / b;

        if yLeft >= 1 && yLeft <= imageHeight
            intersections = [intersections; 1, yLeft];
        end

        if yRight >= 1 && yRight <= imageHeight
            intersections = [intersections; imageWidth, yRight];
        end
    end

    % intersections w top & bottom image borders
    if abs(a) > eps
        xTop = -(b + c) / a;
        xBottom = -(b * imageHeight + c) / a;

        if xTop >= 1 && xTop <= imageWidth
            intersections = [intersections; xTop, 1];
        end

        if xBottom >= 1 && xBottom <= imageWidth
            intersections = [intersections; xBottom, imageHeight];
        end
    end

    if size(intersections, 1) < 2
        return;
    end

    % find the pair of intersections that are farthest apart
    bestPoint1 = intersections(1, :);
    bestPoint2 = intersections(2, :);
    largestDistance = -inf;

    for i = 1:size(intersections, 1) - 1
        for j = i + 1:size(intersections, 1)
            distance = sum( ...
                (intersections(i, :) - intersections(j, :)).^2);

            if distance > largestDistance
                largestDistance = distance;
                bestPoint1 = intersections(i, :);
                bestPoint2 = intersections(j, :);
            end
        end
    end

    plot( ...
        [bestPoint1(1), bestPoint2(1)], ...
        [bestPoint1(2), bestPoint2(2)], ...
        '-', ...
        'Color', lineColor, ...
        'LineWidth', 1.5);
end